package ro.leo.visual;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.Looper;import org.json.*;import java.io.*;
/** Fixed OPP provider operations, invoked through the port's existing root helper. No custom radio stack. */
public final class BluetoothOppBridge {
 static final Uri BASE=Uri.parse("content://com.android.bluetooth.opp/btopp");
 static String clipped(String s,int max){return s==null?"":s.substring(0,Math.min(max,s.length()));}
 public static void main(String[] args){try{if(android.os.Process.myUid()!=0||args.length<1)throw new SecurityException();try(OppProvider resolver=new OppProvider()){JSONObject out=new JSONObject();
  if(args[0].equals("list")&&args.length==1){JSONArray rows=new JSONArray();try(Cursor r=resolver.query(BASE,new String[]{"_id","hint","_data","mimetype","direction","destination","status","total_bytes","current_bytes","confirm","timestamp"},null,null,"_id DESC")){while(r!=null&&r.moveToNext()&&rows.length()<50){JSONObject row=new JSONObject();row.put("id",r.getLong(0)).put("name",clipped(r.getString(1),120)).put("file",clipped(r.getString(2),500)).put("mime",clipped(r.getString(3),100)).put("direction",r.getInt(4)).put("device",clipped(r.getString(5),20)).put("status",r.getInt(6)).put("total",r.getLong(7)).put("current",r.getLong(8)).put("confirm",r.getInt(9)).put("time",r.getLong(10));rows.put(row);}}while(rows.toString().getBytes("UTF-8").length>44000)rows.remove(rows.length()-1);out.put("rows",rows);}
  else if(args[0].equals("send")&&args.length==2){File ownFiles=new File("/data/user/0/ro.leo.visual/files");File f=new File(args[1]);if(!f.getCanonicalFile().getParentFile().equals(ownFiles.getCanonicalFile())||!f.getName().matches("btjob-[A-Za-z0-9-]+\\.json")||f.length()>65536)throw new SecurityException();JSONObject job=new JSONObject(new String(BackupEngine.atomicBytes(f,65536),"UTF-8"));String device=job.getString("device");if(!android.bluetooth.BluetoothAdapter.checkBluetoothAddress(device))throw new IllegalArgumentException();JSONArray uris=job.getJSONArray("uris");if(uris.length()<1||uris.length()>20)throw new IllegalArgumentException();for(int n=0;n<uris.length();n++)if(!"content".equals(Uri.parse(uris.getString(n)).getScheme()))throw new SecurityException();java.util.ArrayList<Uri> files=new java.util.ArrayList<Uri>();for(int n=0;n<uris.length();n++)files.add(Uri.parse(uris.getString(n)));Intent send=new Intent("android.nfc.handover.intent.action.HANDOVER_SEND_MULTIPLE").setComponent(new ComponentName("com.android.bluetooth","com.android.bluetooth.opp.BluetoothOppHandoverReceiver")).setType(job.optString("mime","application/octet-stream")).putParcelableArrayListExtra(Intent.EXTRA_STREAM,files).putExtra(android.bluetooth.BluetoothDevice.EXTRA_DEVICE,android.bluetooth.BluetoothAdapter.getDefaultAdapter().getRemoteDevice(device)).addFlags(Intent.FLAG_RECEIVER_FOREGROUND);resolver.broadcast(send);out.put("queued",true);}
  else if(args.length==2&&(args[0].equals("accept")||args[0].equals("reject")||args[0].equals("cancel"))){long id=Long.parseLong(args[1]);if(id<=0)throw new IllegalArgumentException();Uri row=ContentUris.withAppendedId(BASE,id);int direction,status,confirm;try(Cursor r=resolver.query(row,new String[]{"direction","status","confirm"},null,null,null)){if(r==null||!r.moveToFirst())throw new IOException();direction=r.getInt(0);status=r.getInt(1);confirm=r.getInt(2);}if(status>=200)throw new IllegalStateException();if(args[0].equals("cancel")){if(resolver.delete(row,"status<200",null)!=1)throw new IOException();}else{if(direction!=1||confirm!=0)throw new IllegalStateException();ContentValues v=new ContentValues();v.put("confirm",args[0].equals("accept")?1:3);if(resolver.update(row,v,"direction=1 AND confirm=0 AND status<200",null)!=1)throw new IOException();}}
  else throw new IllegalArgumentException();out.put("success",true);System.out.println(out.toString());}}catch(Throwable e){e.printStackTrace(System.err);System.out.println("{\"success\":false}");System.exit(2);}}
static final class OppProvider implements AutoCloseable {
 final Object manager,provider;final Class<?> am=Class.forName("android.app.IActivityManager"),cp=Class.forName("android.content.IContentProvider");final android.os.IBinder token=new android.os.Binder();
 OppProvider()throws Exception{manager=Class.forName("android.app.ActivityManager").getMethod("getService").invoke(null);Object holder=am.getMethod("getContentProviderExternal",String.class,int.class,android.os.IBinder.class).invoke(manager,BASE.getAuthority(),0,token);if(holder==null)throw new IOException("OPP provider missing");provider=holder.getClass().getField("provider").get(holder);if(provider==null)throw new IOException("OPP provider missing");}
 Cursor query(Uri uri,String[] columns,String where,String[] args,String order)throws Exception{File database=new File("/data/user_de/0/com.android.bluetooth/databases/btopp.db");if(!database.isFile())throw new IOException("OPP metadata database missing");final android.database.sqlite.SQLiteDatabase db=android.database.sqlite.SQLiteDatabase.openDatabase(database.getPath(),null,android.database.sqlite.SQLiteDatabase.OPEN_READONLY|android.database.sqlite.SQLiteDatabase.NO_LOCALIZED_COLLATORS);String id=uri.getLastPathSegment();String selection="btopp".equals(id)?null:"_id=?";String[] selectionArgs=selection==null?null:new String[]{""+Long.parseLong(id)};try{android.database.Cursor cursor=db.query("btopp",columns,selection,selectionArgs,null,null,order,"50");android.database.MatrixCursor copy=new android.database.MatrixCursor(columns);try{while(cursor.moveToNext()){Object[] row=new Object[columns.length];for(int n=0;n<columns.length;n++)row[n]=cursor.isNull(n)?null:cursor.getType(n)==Cursor.FIELD_TYPE_INTEGER?cursor.getLong(n):cursor.getString(n);copy.addRow(row);}}finally{cursor.close();}return copy;}finally{db.close();}}

 int update(Uri uri,ContentValues values,String where,String[] args)throws Exception{return (Integer)cp.getMethod("update",String.class,Uri.class,ContentValues.class,String.class,String[].class).invoke(provider,"root",uri,values,where,args);}
 int delete(Uri uri,String where,String[] args)throws Exception{return (Integer)cp.getMethod("delete",String.class,Uri.class,String.class,String[].class).invoke(provider,"root",uri,where,args);}
 void broadcast(Intent send)throws Exception{for(java.lang.reflect.Method m:am.getMethods())if(m.getName().equals("broadcastIntent")){m.invoke(manager,null,send,send.getType(),null,0,null,null,null,-1,null,false,false,0);return;}throw new NoSuchMethodException();}
 public void close()throws Exception{am.getMethod("removeContentProviderExternal",String.class,android.os.IBinder.class).invoke(manager,BASE.getAuthority(),token);}
}
}
